PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE a2a_checkpoints (
	run_id VARCHAR NOT NULL,
	checkpoint JSON NOT NULL,
	PRIMARY KEY (run_id)
);
CREATE TABLE a2a_tasks (
	id VARCHAR NOT NULL,
	owner VARCHAR NOT NULL,
	task JSON NOT NULL,
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
	PRIMARY KEY (id, owner)
);
CREATE TABLE authz_team (
	id CHAR(32) NOT NULL,
	team_name VARCHAR NOT NULL,
	adom_name VARCHAR NOT NULL,
	description VARCHAR,
	is_active BOOLEAN NOT NULL,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	PRIMARY KEY (id)
);
CREATE TABLE casbin_rule (
	id INTEGER NOT NULL,
	ptype VARCHAR(255) NOT NULL,
	v0 VARCHAR(255),
	v1 VARCHAR(255),
	v2 VARCHAR(255),
	v3 VARCHAR(255),
	v4 VARCHAR(255),
	v5 VARCHAR(255),
	PRIMARY KEY (id)
);
CREATE TABLE job (
	job_id CHAR(32) NOT NULL,
	flow_id CHAR(32) NOT NULL,
	status VARCHAR(11) NOT NULL,
	created_timestamp DATETIME NOT NULL,
	finished_timestamp DATETIME,
	type VARCHAR(10),
	user_id CHAR(32),
	asset_id CHAR(32),
	asset_type VARCHAR,
	dedupe_key VARCHAR,
	job_metadata JSON,
	result JSON,
	error JSON,
	PRIMARY KEY (job_id)
);
CREATE TABLE job_checkpoints (
	id CHAR(32) NOT NULL,
	job_id CHAR(32) NOT NULL,
	kind VARCHAR NOT NULL,
	blob TEXT NOT NULL,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_job_checkpoints_job_id_kind UNIQUE (job_id, kind)
);
CREATE TABLE job_events (
	id CHAR(32) NOT NULL,
	job_id CHAR(32) NOT NULL,
	seq INTEGER NOT NULL,
	event_type VARCHAR NOT NULL,
	payload JSON,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_job_events_job_id_seq UNIQUE (job_id, seq)
);
CREATE TABLE memory_base (
	name VARCHAR NOT NULL,
	flow_id CHAR(32) NOT NULL,
	user_id CHAR(32) NOT NULL,
	threshold INTEGER NOT NULL,
	auto_capture BOOLEAN NOT NULL,
	embedding_model VARCHAR NOT NULL,
	preprocessing BOOLEAN NOT NULL,
	preproc_model VARCHAR,
	preproc_instructions VARCHAR,
	preproc_kill_phrase VARCHAR,
	id CHAR(32) NOT NULL,
	kb_name VARCHAR NOT NULL,
	created_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_memory_base_user_name UNIQUE (user_id, name)
);
CREATE TABLE user (
	id CHAR(32) NOT NULL,
	username VARCHAR NOT NULL,
	password VARCHAR NOT NULL,
	profile_image VARCHAR,
	is_active BOOLEAN NOT NULL,
	is_superuser BOOLEAN NOT NULL,
	create_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	last_login_at DATETIME,
	store_api_key VARCHAR,
	optins JSON,
	PRIMARY KEY (id),
	UNIQUE (id)
);
