CREATE TABLE authz_audit_log (
	id CHAR(32) NOT NULL,
	user_id CHAR(32),
	action VARCHAR NOT NULL,
	resource_type VARCHAR,
	resource_id CHAR(32),
	result VARCHAR NOT NULL,
	details JSON,
	timestamp DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT ck_authz_audit_log_result_enum CHECK (result IN ('allow', 'deny', 'owner_override')),
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE SET NULL
);
CREATE TABLE authz_role (
	id CHAR(32) NOT NULL,
	name VARCHAR NOT NULL,
	description VARCHAR,
	is_system BOOLEAN NOT NULL,
	permissions JSON NOT NULL,
	parent_role_id CHAR(32),
	workspace_id CHAR(32),
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	created_by CHAR(32),
	PRIMARY KEY (id),
	FOREIGN KEY(parent_role_id) REFERENCES authz_role (id) ON DELETE SET NULL,
	FOREIGN KEY(created_by) REFERENCES user (id) ON DELETE SET NULL
);
