CREATE TABLE flow_version_deployment_attachment (
	id CHAR(32) NOT NULL,
	user_id CHAR(32) NOT NULL,
	flow_version_id CHAR(32) NOT NULL,
	deployment_id CHAR(32) NOT NULL,
	provider_snapshot_id VARCHAR,
	created_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
	updated_at DATETIME DEFAULT CURRENT_TIMESTAMP NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_flow_version_deployment UNIQUE (flow_version_id, deployment_id),
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE,
	FOREIGN KEY(flow_version_id) REFERENCES flow_version (id) ON DELETE CASCADE,
	FOREIGN KEY(deployment_id) REFERENCES deployment (id) ON DELETE CASCADE
);
CREATE TABLE span (
	name VARCHAR NOT NULL,
	span_type VARCHAR(9) NOT NULL,
	status VARCHAR(5) NOT NULL,
	start_time DATETIME NOT NULL,
	end_time DATETIME,
	latency_ms INTEGER NOT NULL,
	inputs JSON,
	outputs JSON,
	error TEXT,
	span_kind VARCHAR(8) NOT NULL,
	attributes JSON,
	id CHAR(32) NOT NULL,
	trace_id CHAR(32) NOT NULL,
	parent_span_id CHAR(32),
	PRIMARY KEY (id),
	FOREIGN KEY(trace_id) REFERENCES trace (id) ON DELETE CASCADE,
	FOREIGN KEY(parent_span_id) REFERENCES span (id)
);
CREATE TABLE alembic_version (
	version_num VARCHAR(32) NOT NULL,
	CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);
INSERT INTO alembic_version VALUES('d19e7b3c5a42');
CREATE TABLE IF NOT EXISTS "apikey" (
	name VARCHAR,
	last_used_at DATETIME,
	total_uses INTEGER NOT NULL,
	is_active BOOLEAN NOT NULL,
	expires_at DATETIME,
	id CHAR(32) NOT NULL,
	created_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	api_key VARCHAR NOT NULL,
	api_key_hash VARCHAR,
	user_id CHAR(32) NOT NULL,
	PRIMARY KEY (id),
	UNIQUE (id),
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE IF NOT EXISTS "flow" (
	name VARCHAR NOT NULL,
	description TEXT,
	icon_bg_color VARCHAR,
	gradient VARCHAR,
	is_component BOOLEAN,
	updated_at DATETIME,
	webhook BOOLEAN,
	endpoint_name VARCHAR,
	data JSON,
	mcp_enabled BOOLEAN,
	action_name VARCHAR,
	action_description TEXT,
	access_type VARCHAR(7) DEFAULT 'PRIVATE' NOT NULL,
	flow_type VARCHAR(8) DEFAULT 'workflow' NOT NULL,
	a2a_enabled BOOLEAN DEFAULT 0,
	a2a_card_overrides JSON,
	id CHAR(32) NOT NULL,
	user_id CHAR(32),
	icon VARCHAR,
	tags JSON,
	locked BOOLEAN,
	folder_id CHAR(32),
	workspace_id CHAR(32),
	fs_path VARCHAR,
	PRIMARY KEY (id),
	CONSTRAINT unique_flow_name UNIQUE (user_id, name),
	CONSTRAINT unique_flow_endpoint_name UNIQUE (user_id, endpoint_name),
	CONSTRAINT fk_flow_user_id_user FOREIGN KEY(user_id) REFERENCES user (id),
	FOREIGN KEY(folder_id) REFERENCES folder (id),
	UNIQUE (id)
);
INSERT INTO flow VALUES('Fixture nested groups','A group inside a group.',NULL,NULL,0,'2026-10-27 18:15:28.242345',0,NULL,'{"nodes": [{"id": "groupComponent-TMEDk", "type": "genericNode", "position": {"x": 0, "y": 0.0}, "data": {"id": "groupComponent-TMEDk", "type": "GroupNode", "node": {"display_name": "Group", "documentation": "", "description": "", "template": {"code_ChatInput-5XU72": {"advanced": true, "api_editable": false, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": false, "title_case": false, "type": "code", "value": "from lfx.base.data.utils import IMG_FILE_TYPES, TEXT_FILE_TYPES\nfrom lfx.base.io.chat import ChatComponent\nfrom lfx.inputs.inputs import BoolInput\nfrom lfx.io import (\n    DropdownInput,\n    FileInput,\n    MessageTextInput,\n    MultilineInput,\n    Output,\n)\nfrom lfx.schema.image import get_file_paths\nfrom lfx.schema.message import Message\nfrom lfx.services.deps import get_settings_service\nfrom lfx.utils.constants import (\n    MESSAGE_SENDER_AI,\n    MESSAGE_SENDER_NAME_USER,\n    MESSAGE_SENDER_USER,\n)\nfrom lfx.utils.file_path_security import (\n    component_file_access_scopes,\n    enforce_local_file_access,\n    is_local_file_access_restricted,\n)\n\n\nclass ChatInput(ChatComponent):\n    display_name = \"Chat Input\"\n    description = \"Get chat inputs from the Playground.\"\n    documentation: str = \"https://docs.langflow.org/chat-input-and-output\"\n    icon = \"MessagesSquare\"\n    name = \"ChatInput\"\n    minimized = True\n\n    inputs = [\n        MultilineInput(\n            name=\"input_value\",\n            display_name=\"Input Text\",\n            value=\"\",\n            info=\"Message to be passed as input.\",\n            input_types=[],\n        ),\n        BoolInput(\n            name=\"should_store_message\",\n            display_name=\"Store Messages\",\n            info=\"Store the message in the history.\",\n            value=True,\n            advanced=True,\n        ),\n        DropdownInput(\n            name=\"sender\",\n            display_name=\"Sender Type\",\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\n            value=MESSAGE_SENDER_USER,\n            info=\"Type of sender.\",\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"sender_name\",\n            display_name=\"Sender Name\",\n            info=\"Name of the sender.\",\n            value=MESSAGE_SENDER_NAME_USER,\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"session_id\",\n            display_name=\"Session ID\",\n            info=\"The session ID of the chat. If empty, the current session ID parameter will be used.\",\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"context_id\",\n            display_name=\"Context ID\",\n            info=\"The context ID of the chat. Adds an extra layer to the local memory.\",\n            value=\"\",\n            advanced=True,\n        ),\n        FileInput(\n            name=\"files\",\n            display_name=\"Files\",\n            file_types=TEXT_FILE_TYPES + IMG_FILE_TYPES,\n            info=\"Files to be sent with the message.\",\n            advanced=True,\n            is_list=True,\n            temp_file=True,\n        ),\n    ]\n    outputs = [\n        Output(display_name=\"Chat Message\", name=\"message\", method=\"message_response\"),\n    ]\n\n    async def message_response(self) -> Message:\n        # Ensure files is a list and filter out empty/None values\n        files = self.files if self.files else []\n        if files and not isinstance(files, list):\n            files = [files]\n        # Filter out None/empty values\n        files = [f for f in files if f is not None and f != \"\"]\n\n        # Build endpoints inject caller-controlled file references directly into\n        # ChatInput. Resolve and validate local references before the Message can\n        # later read them while constructing model attachment content.\n        if files:\n            settings_service = get_settings_service()\n            storage_type = getattr(getattr(settings_service, \"settings\", None), \"storage_type\", \"local\")\n            # The storage factory falls back to local storage for unsupported\n            # values, so only the explicitly configured S3 backend may bypass\n            # filesystem containment.\n            if str(storage_type).lower() != \"s3\" and is_local_file_access_restricted():\n                scope_ids = list(component_file_access_scopes(self))\n                # Public executions replace graph.flow_id with a per-visitor\n                # virtual ID. Only the server-populated source provenance may\n                # restore the already-validated public attachment namespace.\n                source_flow_id = getattr(self.graph, \"source_flow_id\", None)\n                if source_flow_id:\n                    scope_ids.append(source_flow_id)\n                for file_path in get_file_paths(files):\n                    enforce_local_file_access(file_path, scope_ids=scope_ids)\n\n        session_id = self.session_id or self.graph.session_id or \"\"\n        message = await Message.create(\n            text=self.input_value,\n            sender=self.sender,\n            sender_name=self.sender_name,\n            session_id=session_id,\n            context_id=self.context_id,\n            files=files,\n        )\n        if session_id and isinstance(message, Message) and self.should_store_message:\n            stored_message = await self.send_message(\n                message,\n            )\n            self.message.value = stored_message\n            message = stored_message\n\n        self.status = message\n        return message\n", "proxy": {"id": "ChatInput-5XU72", "field": "code"}, "display_name": "Code"}, "