INSERT INTO flow VALUES('Fixture saved component','A saved component.',NULL,NULL,1,'2026-10-27 18:15:28.250018',0,NULL,'{"nodes": [{"id": "ChatInput-InXNw", "type": "genericNode", "position": {"x": 0, "y": 0}, "selected": false, "data": {"id": "ChatInput-InXNw", "type": "ChatInput", "node": {"base_classes": ["Message"], "beta": false, "conditional_paths": [], "custom_fields": {}, "description": "Get chat inputs from the Playground.", "display_name": "Chat Input", "documentation": "https://docs.langflow.org/chat-input-and-output", "edited": false, "field_order": ["input_value", "should_store_message", "sender", "sender_name", "session_id", "context_id", "files"], "frozen": false, "icon": "MessagesSquare", "legacy": false, "metadata": {"code_hash": "45974e6b1909", "dependencies": {"dependencies": [{"name": "lfx", "version": null}], "total_dependencies": 1}, "module": "lfx.components.input_output.chat.ChatInput"}, "minimized": true, "output_types": [], "outputs": [{"allows_loop": false, "cache": true, "display_name": "Chat Message", "group_outputs": false, "method": "message_response", "name": "message", "selected": "Message", "tool_mode": true, "types": ["Message"], "value": "__UNDEFINED__", "hidden": false, "options": null, "required_inputs": null}], "pinned": false, "template": {"_type": "Component", "code": {"advanced": true, "api_editable": false, "dynamic": true, "fileTypes": [], "file_path": "", "info": "", "list": false, "load_from_db": false, "multiline": true, "name": "code", "password": false, "placeholder": "", "required": true, "show": true, "title_case": false, "type": "code", "value": "from lfx.base.data.utils import IMG_FILE_TYPES, TEXT_FILE_TYPES\nfrom lfx.base.io.chat import ChatComponent\nfrom lfx.inputs.inputs import BoolInput\nfrom lfx.io import (\n    DropdownInput,\n    FileInput,\n    MessageTextInput,\n    MultilineInput,\n    Output,\n)\nfrom lfx.schema.image import get_file_paths\nfrom lfx.schema.message import Message\nfrom lfx.services.deps import get_settings_service\nfrom lfx.utils.constants import (\n    MESSAGE_SENDER_AI,\n    MESSAGE_SENDER_NAME_USER,\n    MESSAGE_SENDER_USER,\n)\nfrom lfx.utils.file_path_security import (\n    component_file_access_scopes,\n    enforce_local_file_access,\n    is_local_file_access_restricted,\n)\n\n\nclass ChatInput(ChatComponent):\n    display_name = \"Chat Input\"\n    description = \"Get chat inputs from the Playground.\"\n    documentation: str = \"https://docs.langflow.org/chat-input-and-output\"\n    icon = \"MessagesSquare\"\n    name = \"ChatInput\"\n    minimized = True\n\n    inputs = [\n        MultilineInput(\n            name=\"input_value\",\n            display_name=\"Input Text\",\n            value=\"\",\n            info=\"Message to be passed as input.\",\n            input_types=[],\n        ),\n        BoolInput(\n            name=\"should_store_message\",\n            display_name=\"Store Messages\",\n            info=\"Store the message in the history.\",\n            value=True,\n            advanced=True,\n        ),\n        DropdownInput(\n            name=\"sender\",\n            display_name=\"Sender Type\",\n            options=[MESSAGE_SENDER_AI, MESSAGE_SENDER_USER],\n            value=MESSAGE_SENDER_USER,\n            info=\"Type of sender.\",\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"sender_name\",\n            display_name=\"Sender Name\",\n            info=\"Name of the sender.\",\n            value=MESSAGE_SENDER_NAME_USER,\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"session_id\",\n            display_name=\"Session ID\",\n            info=\"The session ID of the chat. If empty, the current session ID parameter will be used.\",\n            advanced=True,\n        ),\n        MessageTextInput(\n            name=\"context_id\",\n            display_name=\"Context ID\",\n            info=\"The context ID of the chat. Adds an extra layer to the local memory.\",\n            value=\"\",\n            advanced=True,\n        ),\n        FileInput(\n            name=\"files\",\n            display_name=\"Files\",\n            file_types=TEXT_FILE_TYPES + IMG_FILE_TYPES,\n            info=\"Files to be sent with the message.\",\n            advanced=True,\n            is_list=True,\n            temp_file=True,\n        ),\n    ]\n    outputs = [\n        Output(display_name=\"Chat Message\", name=\"message\", method=\"message_response\"),\n    ]\n\n    async def message_response(self) -> Message:\n        # Ensure files is a list and filter out empty/None values\n        files = self.files if self.files else []\n        if files and not isinstance(files, list):\n            files = [files]\n        # Filter out None/empty values\n        files = [f for f in files if f is not None and f != \"\"]\n\n        # Build endpoints inject caller-controlled file references directly into\n        # ChatInput. Resolve and validate local references before the Message can\n        # later read them while constructing model attachment content.\n        if files:\n            settings_service = get_settings_service()\n            storage_type = getattr(getattr(settings_service, \"settings\", None), \"storage_type\", \"local\")\n            # The storage factory falls back to local storage for unsupported\n            # values, so only the explicitly configured S3 backend may bypass\n            # filesystem containment.\n            if str(storage_type).lower() != \"s3\" and is_local_file_access_restricted():\n                scope_ids = list(component_file_access_scopes(self))\n                # Public executions replace graph.flow_id with a per-visitor\n                # virtual ID. Only the server-populated source provenance may\n                # restore the already-validated public attachment namespace.\n                source_flow_id = getattr(self.graph, \"source_flow_id\", None)\n                if source_flow_id:\n                    scope_ids.append(source_flow_id)\n                for file_path in get_file_paths(files):\n                    enforce_local_file_access(file_path, scope_ids=scope_ids)\n\n        session_id = self.session_id or self.graph.session_id or \"\"\n        message = await Message.create(\n            text=self.input_value,\n            sender=self.sender,\n            sender_name=self.sender_name,\n            session_id=session_id,\n            context_id=self.context_id,\n            files=files,\n        )\n        if session_id and isinstance(message, Message) and self.should_store_message:\n            stored_message = await self.send_message(\n                message,\n            )\n            self.message.value = stored_message\n            message = stored_message\n\n        self.status = message\n        return message\n"}, "context_id": {"_input_type": "MessageTextInput", "advanced": true, "api_editable": false, "display_name": "Context ID", "dynamic": false, "info": "The context ID of the chat. Adds an extra layer to the local memory.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "context_id", "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "track_in_telemetry": false, "type": "str", "value": ""}, "files": {"_input_type": "FileInput", "advanced": true, "api_editable": false, "display_name": "Files", "dynamic": false, "fileTypes": ["csv", "json", "pdf", "txt", "md", "mdx", "yaml", "yml", "xml", "html", "htm", "docx", "py", "sh", "sql", "js", "ts", "tsx", "jpg", "jpeg", "png", "bmp", "image"], "file_path": "", "info": "Files to be sent with the message.", "list": true, "list_add_label": "Add More", "name": "files", "override_skip": false, "placeholder": "", "required": false, "show": true, "temp_file": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "track_in_telemetry": false, "type": "file", "value": ""}, "input_value": {"_input_type": "MultilineInput", "advanced": false, "ai_enabled": false, "api_editable": false, "copy_field": false, "display_name": "Input Text", "dynamic": false, "info": "Message to be passed as input.", "input_types": [], "list": false, "list_add_label": "Add More", "load_from_db": false, "multiline": true, "name": "input_value", "override_skip": false, "password": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "track_in_telemetry": false, "type": "str", "value": ""}, "sender": {"_input_type": "DropdownInput", "advanced": true, "api_editable": false, "combobox": false, "dialog_inputs": {}, "display_name": "Sender Type", "dynamic": false, "external_options": {}, "info": "Type of sender.", "name": "sender", "options": ["Machine", "User"], "options_metadata": [], "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "toggle": false, "tool_mode": false, "trace_as_metadata": true, "track_in_telemetry": true, "type": "str", "value": "User"}, "sender_name": {"_input_type": "MessageTextInput", "advanced": true, "api_editable": false, "display_name": "Sender Name", "dynamic": false, "info": "Name of the sender.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "sender_name", "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "track_in_telemetry": false, "type": "str", "value": "User"}, "session_id": {"_input_type": "MessageTextInput", "advanced": true, "api_editable": false, "display_name": "Session ID", "dynamic": false, "info": "The session ID of the chat. If empty, the current session ID parameter will be used.", "input_types": ["Message"], "list": false, "list_add_label": "Add More", "load_from_db": false, "name": "session_id", "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_input": true, "trace_as_metadata": true, "track_in_telemetry": false, "type": "str", "value": ""}, "should_store_message": {"_input_type": "BoolInput", "advanced": true, "api_editable": false, "display_name": "Store Messages", "dynamic": false, "info": "Store the message in the history.", "list": false, "list_add_label": "Add More", "name": "should_store_message", "override_skip": false, "placeholder": "", "required": false, "show": true, "title_case": false, "tool_mode": false, "trace_as_metadata": true, "track_in_telemetry": true, "type": "bool", "value": true}}, "tool_mode": false}, "showNode": true}}], "edges": []}',0,NULL,NULL,'PRIVATE','workflow',0,'null','9ca2cc288e7548af96eaac2625d2ae7a','1c2a710b2bab4c7ca2b4664b93a35589',NULL,'null',0,'4f8ee83c692e4577a47e9a1ac2aa4e85',NULL,NULL);
CREATE TABLE IF NOT EXISTS "vertex_build" (
	timestamp DATETIME NOT NULL,
	id VARCHAR NOT NULL,
	data JSON,
	artifacts JSON,
	params TEXT,
	build_id CHAR(32) NOT NULL,
	flow_id CHAR(32) NOT NULL,
	valid BOOLEAN NOT NULL, job_id CHAR(32),
	CONSTRAINT pk_vertex_build PRIMARY KEY (build_id)
);
CREATE TABLE IF NOT EXISTS "transaction" (
	timestamp DATETIME NOT NULL,
	vertex_id VARCHAR NOT NULL,
	target_id VARCHAR,
	inputs JSON,
	outputs JSON,
	status VARCHAR NOT NULL,
	id CHAR(32) NOT NULL,
	flow_id CHAR(32) NOT NULL,
	error VARCHAR,
	CONSTRAINT pk_transaction PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS "trace" (
	name VARCHAR NOT NULL,
	status VARCHAR(5) NOT NULL,
	start_time DATETIME NOT NULL,
	end_time DATETIME,
	total_latency_ms INTEGER NOT NULL,
	total_tokens INTEGER NOT NULL,
	flow_id CHAR(32) NOT NULL,
	session_id VARCHAR,
	id CHAR(32) NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT fk_trace_flow_id_flow FOREIGN KEY(flow_id) REFERENCES flow (id) ON DELETE CASCADE,
	FOREIGN KEY(flow_id) REFERENCES flow (id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "file" (
	id CHAR(32) NOT NULL,
	user_id CHAR(32) NOT NULL,
	name VARCHAR NOT NULL,
	path VARCHAR NOT NULL,
	size INTEGER NOT NULL,
	provider VARCHAR,
	created_at DATETIME NOT NULL,
	updated_at DATETIME NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT file_name_user_id_key UNIQUE (name, user_id),
	CONSTRAINT fk_file_user_id_user FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE,
	FOREIGN KEY(user_id) REFERENCES user (id)
);
CREATE TABLE IF NOT EXISTS "deployment_provider_account" (
	id CHAR(32) NOT NULL,
	user_id CHAR(32) NOT NULL,
	provider_tenant_id VARCHAR,
	name VARCHAR NOT NULL,
	provider_url VARCHAR NOT NULL,
	api_key VARCHAR NOT NULL,
	created_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	updated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	provider_key VARCHAR(19) NOT NULL,
	PRIMARY KEY (id),
	CONSTRAINT uq_deployment_provider_account_user_url_tenant UNIQUE (user_id, provider_url, provider_tenant_id),
	CONSTRAINT uq_deployment_provider_account_provider_name UNIQUE (user_id, provider_key, name),
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "message" (
	timestamp DATETIME NOT NULL,
	sender VARCHAR NOT NULL,
	sender_name VARCHAR NOT NULL,
	session_id VARCHAR NOT NULL,
	text TEXT,
	id CHAR(32) NOT NULL,
	flow_id CHAR(32),
	files JSON,
	error BOOLEAN DEFAULT 0 NOT NULL,
	edit BOOLEAN DEFAULT 0 NOT NULL,
	properties JSON,
	category TEXT,
	content_blocks JSON,
	context_id VARCHAR,
	session_metadata JSON,
	run_id CHAR(32),
	is_output BOOLEAN DEFAULT false NOT NULL, user_id CHAR(32),
	CONSTRAINT pk_message PRIMARY KEY (id)
);
CREATE TABLE IF NOT EXISTS "deployment" (
	id CHAR(32) NOT NULL,
	resource_key VARCHAR NOT NULL,
	user_id CHAR(32) NOT NULL,
	project_id CHAR(32) NOT NULL,
	deployment_provider_account_id CHAR(32) NOT NULL,
	workspace_id CHAR(32),
	display_name VARCHAR,
	description TEXT,
	created_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	updated_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL,
	deployment_type VARCHAR(5),
	PRIMARY KEY (id),
	CONSTRAINT uq_deployment_resource_key_in_provider UNIQUE (deployment_provider_account_id, resource_key),
	FOREIGN KEY(user_id) REFERENCES user (id) ON DELETE CASCADE,
	FOREIGN KEY(project_id) REFERENCES folder (id) ON DELETE CASCADE,
	FOREIGN KEY(deployment_provider_account_id) REFERENCES deployment_provider_account (id) ON DELETE CASCADE
);
CREATE TABLE IF NOT EXISTS "execution_signals" (
	id CHAR(32) NOT NULL,
	job_id CHAR(32) NOT NULL,
	signal_type VARCHAR(6) NOT NULL,
	data JSON,
	created_at DATETIME NOT NULL,
	consumed_at DATETIME,
	PRIMARY KEY (id)
);
